@Component("softwareLoad-handler")
@ProcessingGroup("softwareLoad-processing-group")
public class SoftwareLoadEventHandler {
	
	// core constructor
	SoftwareLoadEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateSoftwareLoadEvent
     */
    @EventHandler
    public void handle( CreateSoftwareLoadEvent event) {
        entityManager.persist(new SoftwareLoad(event.getSoftwareLoadId(), event.getVersion(), event.getConnectedAircraft(), event.getAvionicsSuite(), event.getLoadType()));
    }

    /*
     * @param	event UpdateSoftwareLoadEvent
     */
    @EventHandler
    public SoftwareLoad handle( UpdateSoftwareLoadEvent event) {
    	entityManager.merge(new SoftwareLoad(event.getSoftwareLoadId(), event.getVersion(), event.getConnectedAircraft(), event.getAvionicsSuite(), event.getLoadType()));
    }
    
    /*
     * @param	event DeleteSoftwareLoadEvent
     */
    @EventHandler
    public void on( DeleteSoftwareLoadEvent event) {
    	SoftwareLoad entity = new SoftwareLoad();
   
    	// ------------------------------------------
    	// apply the SoftwareLoadId
    	// ------------------------------------------
    	entity.setSoftwareLoadId( event.getSoftwareLoadId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final SoftwareLoadRepository softwareLoadEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(SoftwareLoadEventHandler.class.getName());

}
